    "ingestion.uploadCsv": {
        parameters: {
            query: {
                /** @description Target planning cycle ID. */
                cycle_id: number;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "multipart/form-data": {
                    /** Format: binary */
                    file: string;
                };
            };
        };
        responses: {
            /** @description Import complete. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["CsvImportResult"];
                };
            };
            /** @description The upload is not named `.csv`. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            403: components["responses"]["Forbidden"];
            404: components["responses"]["NotFound"];
            /** @description The file is larger than `CSV_UPLOAD_MAX_MB` (25 MB unless the instance sets it), and nothing was imported. Behind the bundled nginx a request over 25 MB is refused by nginx itself, also with 413 but with an HTML body. */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description The file was refused and nothing was saved. `detail` says why, and names the line where the file is at fault: a missing column, an unparseable time, an address already belonging to somebody else, a room already taken for that window, a lead who has no account, a member or lead who has been deactivated. Where the failure is the server's rather than the file's, `detail` says only that the import failed and that the reason is in the server log. */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
        };
    };
